 2→const OFFLINE_URL = '/offline.html';
 3→
 4→self.addEventListener('install', (event) => {
 5→    event.waitUntil(
 6→        caches.open(CACHE_NAME).then((cache) => cache.add(OFFLINE_URL))
 7→    );
 8→    self.skipWaiting();
 9→});
10→
11→self.addEventListener('activate', (event) => {
12→    event.waitUntil(
13→        caches.keys().then((keys) =>
14→            Promise.all(
15→                keys
16→                    .filter((key) => key !== CACHE_NAME)
17→                    .map((key) => caches.delete(key))
18→            )
19→        )
20→    );
21→    self.clients.claim();
22→});
23→
24→self.addEventListener('fetch', (event) => {
25→    if (event.request.mode === 'navigate') {
26→        event.respondWith(
27→            fetch(event.request).catch(() =>
28→                caches.match(OFFLINE_URL)
29→            )
30→        );
31→    }
32→});
